const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let idx = 0;

const nextInt = () => parseInt(input[idx++], 10);

const v1 = nextInt();
const v2 = nextInt();
let t = nextInt();
const d = nextInt();

let path = 0;
let maxSpeed = 0;

for (; t > 0; t--) {
    path += v1;
    maxSpeed = v2 + d * (t - 2);

    if (maxSpeed > v1) {
        if (v1 + d > maxSpeed) {
            v1 = maxSpeed;
        } else {
            v1 += d;
        }
    } else if (maxSpeed < v1) {
        if (v1 - d < maxSpeed) {
            v1 = maxSpeed;
        } else {
            v1 -= d;
        }
    }
}

console.log(path);

